using FiveSmartFarmCreators.Ichu.Platform.OperationsMonitoring.Domain.Model.ValueObjects;

namespace FiveSmartFarmCreators.Ichu.Platform.OperationsMonitoring.Domain.Model.Commands;

/// <summary>
///     A change recorded by an Edge Gateway for an existing alert: new evidence, a return to the permitted area, or
///     local attention registered by an authorized user. The kind is empty when the gateway sent an unknown value.
/// </summary>
/// <param name="OperationId">The identifier generated by the Edge Gateway for the change.</param>
/// <param name="AlertId">The alert the change applies to.</param>
/// <param name="Kind">The kind of change, or <see langword="null"/> when missing or unknown.</param>
/// <param name="DeviceId">The device that captured the evidence readings; the alert device when omitted.</param>
/// <param name="ReadingIds">The evidence readings, for evidence changes.</param>
/// <param name="OccurredAt">The instant the change happened, for return and attention changes.</param>
/// <param name="AuthorId">The account that registered the attention, for attention changes.</param>
/// <param name="Finding">What the author found, for attention changes.</param>
/// <param name="Action">What the author did, for attention changes.</param>
/// <param name="ExpectedVersion">The alert version last read by the author, for attention changes.</param>
public record EdgeAlertChangeEntry(
    Guid OperationId,
    Guid AlertId,
    AlertChangeKind? Kind,
    Guid? DeviceId,
    IReadOnlyList<Guid> ReadingIds,
    DateTimeOffset? OccurredAt,
    Guid? AuthorId,
    string? Finding,
    string? Action,
    int? ExpectedVersion);
